'use client';

import {
  PasswordInput as PasswordInputPrimitive,
  usePasswordInput,
  usePasswordInputContext,
} from '@ark-ui/react/password-input';
import { clsx } from 'clsx';
import type { ComponentProps, ComponentRef } from 'react';
import { forwardRef } from 'react';
import { EyeClosedIcon, EyeIcon } from '@/lib/moduix/icons/ui';
import styles from './PasswordInput.module.css';

const PasswordInput = forwardRef<
  ComponentRef<typeof PasswordInputPrimitive.Root>,
  ComponentProps<typeof PasswordInputPrimitive.Root>
>(function PasswordInput({ className, ...props }, ref) {
  return (
    <PasswordInputPrimitive.Root
      ref={ref}
      className={clsx(styles.root, className)}
      {...props}
      data-slot="password-input-root"
    />
  );
});

const PasswordInputRootProvider = forwardRef<
  ComponentRef<typeof PasswordInputPrimitive.RootProvider>,
  ComponentProps<typeof PasswordInputPrimitive.RootProvider>
>(function PasswordInputRootProvider({ className, ...props }, ref) {
  return (
    <PasswordInputPrimitive.RootProvider
      ref={ref}
      className={clsx(styles.root, className)}
      {...props}
      data-slot="password-input-root-provider"
    />
  );
});

const PasswordInputLabel = forwardRef<
  ComponentRef<typeof PasswordInputPrimitive.Label>,
  ComponentProps<typeof PasswordInputPrimitive.Label>
>(function PasswordInputLabel({ className, ...props }, ref) {
  return (
    <PasswordInputPrimitive.Label
      ref={ref}
      className={clsx(styles.label, className)}
      {...props}
      data-slot="password-input-label"
    />
  );
});

const PasswordInputControl = forwardRef<
  ComponentRef<typeof PasswordInputPrimitive.Control>,
  ComponentProps<typeof PasswordInputPrimitive.Control>
>(function PasswordInputControl({ className, ...props }, ref) {
  return (
    <PasswordInputPrimitive.Control
      ref={ref}
      className={clsx(styles.control, className)}
      {...props}
      data-slot="password-input-control"
    />
  );
});

const PasswordInputInput = forwardRef<
  ComponentRef<typeof PasswordInputPrimitive.Input>,
  ComponentProps<typeof PasswordInputPrimitive.Input>
>(function PasswordInputInput({ className, ...props }, ref) {
  return (
    <PasswordInputPrimitive.Input
      ref={ref}
      className={clsx(styles.input, className)}
      {...props}
      data-slot="password-input-input"
    />
  );
});

const PasswordInputVisibilityTrigger = forwardRef<
  ComponentRef<typeof PasswordInputPrimitive.VisibilityTrigger>,
  ComponentProps<typeof PasswordInputPrimitive.VisibilityTrigger>
>(function PasswordInputVisibilityTrigger({ className, ...props }, ref) {
  return (
    <PasswordInputPrimitive.VisibilityTrigger
      ref={ref}
      className={clsx(styles.visibilityTrigger, className)}
      {...props}
      data-slot="password-input-visibility-trigger"
    />
  );
});

const PasswordInputIndicator = forwardRef<
  ComponentRef<typeof PasswordInputPrimitive.Indicator>,
  ComponentProps<typeof PasswordInputPrimitive.Indicator>
>(function PasswordInputIndicator({ className, children, fallback, ...props }, ref) {
  return (
    <PasswordInputPrimitive.Indicator
      ref={ref}
      className={clsx(styles.indicator, className)}
      fallback={fallback ?? <EyeClosedIcon />}
      {...props}
      data-slot="password-input-indicator"
    >
      {children ?? <EyeIcon />}
    </PasswordInputPrimitive.Indicator>
  );
});

type PasswordInputFieldProps = Omit<
  ComponentProps<typeof PasswordInputControl>,
  'asChild' | 'children'
>;

const PasswordInputField = forwardRef<
  ComponentRef<typeof PasswordInputPrimitive.Control>,
  PasswordInputFieldProps
>(function PasswordInputField(props, ref) {
  return (
    <PasswordInputControl ref={ref} {...props}>
      <PasswordInputInput />
      <PasswordInputVisibilityTrigger>
        <PasswordInputIndicator />
      </PasswordInputVisibilityTrigger>
    </PasswordInputControl>
  );
});

const PasswordInputContext = PasswordInputPrimitive.Context;

export {
  PasswordInput,
  PasswordInputContext,
  PasswordInputControl,
  PasswordInputField,
  PasswordInputIndicator,
  PasswordInputInput,
  PasswordInputLabel,
  PasswordInputRootProvider,
  PasswordInputVisibilityTrigger,
  usePasswordInput,
  usePasswordInputContext,
};

@layer moduix.components {
  .root {
    box-sizing: border-box;
    display: flex;
    flex-direction: column;
    gap: var(--moduix-password-input-gap, var(--moduix-spacing-1));
    width: var(--moduix-password-input-width, 100%);
    max-width: var(--moduix-password-input-max-width, none);
    color: var(--moduix-password-input-color, var(--moduix-color-foreground));
    &[data-disabled] {
      opacity: var(--moduix-password-input-disabled-opacity, var(--moduix-opacity-disabled));
    }
  }

  .label {
    display: inline-flex;
    align-items: center;
    gap: var(--moduix-password-input-label-gap, var(--moduix-spacing-1));
    color: var(--moduix-password-input-label-color, var(--moduix-color-foreground));
    font-size: var(--moduix-password-input-label-font-size, var(--moduix-text-sm));
    font-weight: var(--moduix-password-input-label-font-weight, var(--moduix-weight-medium));
    line-height: var(--moduix-password-input-label-line-height, var(--moduix-line-height-text-sm));
  }

  .control {
    box-sizing: border-box;
    display: flex;
    align-items: center;
    width: 100%;
    min-height: var(--moduix-password-input-height, var(--moduix-size-md));
    border: var(--moduix-border-width-sm) solid
      var(--moduix-password-input-border-color, var(--moduix-color-border));
    border-radius: var(--moduix-password-input-radius, var(--moduix-radius-md));
    padding-inline-end: var(--moduix-password-input-trigger-inset, var(--moduix-spacing-2));
    background-color: var(--moduix-password-input-bg, var(--moduix-color-background));
    color: var(--moduix-password-input-color, var(--moduix-color-foreground));
    outline: var(--moduix-border-width-sm) solid transparent;
    outline-offset: calc(0px - var(--moduix-border-width-sm));
    transition:
      border-color var(--moduix-transition-default),
      outline-color var(--moduix-transition-default),
      opacity var(--moduix-transition-default);

    &:focus-within {
      outline-color: var(--moduix-password-input-focus-ring-color, var(--moduix-color-ring));
    }

    &[data-invalid] {
      border-color: var(
        --moduix-password-input-invalid-border-color,
        var(--moduix-color-destructive)
      );

      &:focus-within {
        outline-color: var(
          --moduix-password-input-invalid-focus-ring-color,
          var(--moduix-color-destructive)
        );
      }
    }

    &[data-readonly] {
      background-color: var(--moduix-password-input-readonly-bg, var(--moduix-color-background));
      color: var(--moduix-password-input-readonly-color, var(--moduix-color-foreground));
    }
  }

  .input {
    box-sizing: border-box;
    flex: 1 1 auto;
    min-width: 0;
    min-height: 0;
    margin: 0;
    border: 0;
    border-radius: 0;
    padding: var(--moduix-password-input-padding-y, var(--moduix-spacing-1))
      var(--moduix-password-input-padding-x, var(--moduix-spacing-3));
    background-color: transparent;
    color: var(--moduix-password-input-color, var(--moduix-color-foreground));
    font: inherit;
    font-size: var(--moduix-password-input-font-size, var(--moduix-text-md));
    line-height: var(--moduix-password-input-line-height, var(--moduix-line-height-text-md));
    outline: 0;
    transition: opacity var(--moduix-transition-default);

    &::placeholder {
      color: var(--moduix-password-input-placeholder-color, var(--moduix-color-muted-foreground));
    }

    &:is([data-disabled], :disabled) {
      pointer-events: none;
      opacity: 1;
    }

    &:is(:read-only, [data-readonly]) {
      background-color: transparent;
    }
  }

  .visibilityTrigger {
    display: inline-flex;
    flex-shrink: 0;
    align-items: center;
    justify-content: center;
    width: var(--moduix-password-input-trigger-size, var(--moduix-size-sm));
    min-width: var(--moduix-password-input-trigger-size, var(--moduix-size-sm));
    height: var(--moduix-password-input-trigger-size, var(--moduix-size-sm));
    padding: 0;
    color: var(--moduix-password-input-trigger-color, var(--moduix-color-muted-foreground));
    background: var(--moduix-password-input-trigger-bg, transparent);
    border: 0;
    border-radius: var(--moduix-password-input-trigger-radius, var(--moduix-radius-sm));
    outline: var(--moduix-border-width-sm) solid transparent;
    outline-offset: calc(0px - var(--moduix-border-width-sm));
    cursor: pointer;
    transition:
      color var(--moduix-transition-default),
      outline-color var(--moduix-transition-default),
      opacity var(--moduix-transition-default);

    @media (hover: hover) {
      &:not([data-disabled]):not([data-readonly]):hover {
        color: var(--moduix-password-input-trigger-hover-color, var(--moduix-color-foreground));
      }
    }

    &:focus-visible {
      outline-color: var(--moduix-password-input-focus-ring-color, var(--moduix-color-ring));
    }

    &:is([data-disabled], [data-readonly], :disabled) {
      cursor: default;
      opacity: 1;
    }
  }

  .indicator {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    padding: var(--moduix-password-input-trigger-visual-padding, var(--moduix-spacing-1));
    border-radius: var(--moduix-password-input-trigger-radius, var(--moduix-radius-sm));
    transition:
      background-color var(--moduix-transition-default),
      color var(--moduix-transition-default);

    & svg {
      width: var(
        --moduix-password-input-icon-size,
        var(--moduix-button-icon-size, var(--moduix-spacing-4))
      );
      height: var(
        --moduix-password-input-icon-size,
        var(--moduix-button-icon-size, var(--moduix-spacing-4))
      );
    }
  }

  @media (hover: hover) {
    .visibilityTrigger:not([data-disabled]):not([data-readonly]):hover .indicator {
      background: var(--moduix-password-input-trigger-hover-bg, var(--moduix-color-muted));
    }
  }

  .visibilityTrigger:not([data-disabled]):not([data-readonly]):focus-visible .indicator {
    background: var(--moduix-password-input-trigger-hover-bg, var(--moduix-color-muted));
  }
}
